INSERT INTO public.development_ledger_items (
  stable_key, occurred_on, plan_scope, work_type, section_code, section_title, title, rationale,
  technical_detail, billing_status, amount_cents, prior_invoice_label, sort_order
) VALUES
  ('i1-1', '2026-07-03', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Una misma factura ya no puede enviarse dos veces a R365.', 'Si dos procesos corrían al mismo tiempo, ambos tomaban la misma factura. Ahora cada factura se "aparta" antes de mandarse y el segundo proceso la encuentra ocupada.', 'Claim atómico en 20260703000001_qbo_unified_invoices_claim.sql', 'unpriced', NULL, NULL, 1010),
  ('i1-2', '2026-07-09', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Se destrabó el envío automático de facturas.', 'Un comportamiento inesperado de la capa de base de datos hacía que el envío automático quedara colgado sin error visible.', 'Bug de PostgREST rodeado en el pipeline de envío QBO -> R365', 'unpriced', NULL, NULL, 1020),
  ('i1-3', '2026-07-24', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Los clientes sin FTP ahora sí ven sus facturas mapeadas.', 'Antes, si un cliente no tenía configurado el envío por FTP, el sistema se saltaba también el mapeo. Ahora mapea igual y solo omite el envío.', NULL, 'unpriced', NULL, NULL, 1030),
  ('i1-4', '2026-07-24', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Si marcar una factura como "mapeada" falla, ahora se entera.', 'El resultado de esa operación no se revisaba, así que un fallo pasaba desapercibido y la factura quedaba en un estado incorrecto.', NULL, 'unpriced', NULL, NULL, 1040),
  ('i1-5', '2026-08-06', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Las notas de crédito con importes negativos ya no rompen la validación.', 'Los credit memos llegan con montos negativos por definición y el validador los rechazaba como si fueran un error.', NULL, 'unpriced', NULL, NULL, 1050),
  ('i1-6', '2026-07-24', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'El webhook de QuickBooks ya no se corta a la mitad.', 'Tenía 10 segundos de tiempo máximo y en lotes grandes se cortaba. Ahora tiene 60.', 'maxDuration 10s -> 60s en el handler del webhook QBO', 'unpriced', NULL, NULL, 1060),
  ('i1-7', '2026-07-24', 'integration', 'new', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Soporte de CloudEvents de Intuit y mejoras generales de confiabilidad.', 'El formato de eventos que Intuit está adoptando, más reintentos y trazas en todo el recorrido de la factura.', NULL, 'unpriced', NULL, NULL, 1070),
  ('i1-8', '2026-07-30', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Los avisos de clientes que aún no configuraron el sync se marcan como "ignorados", no como error.', 'Llenaban el registro de errores falsos y escondían los problemas reales.', NULL, 'unpriced', NULL, NULL, 1080),
  ('i1-9', '2026-07-25', 'integration', 'new', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Aviso al superadmin cuando un aviso de QuickBooks no se puede procesar.', 'Antes fallaba en silencio. Ahora llega una alerta con el detalle.', NULL, 'previously_invoiced', NULL, 'Integración QBO→R365: notificación push a superadmin', 1090),
  ('i1-10', '2026-07-14', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Los números de cuenta de clientes cargan mucho más rápido y los que fallan se reintentan solos.', NULL, 'Carga de Account No. paralelizada con reintento de fallidos', 'unpriced', NULL, NULL, 1100),
  ('i1-11', '2026-07-14', 'integration', 'fix', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'El tablero ya no se rompe cuando Intuit limita las peticiones.', 'Un error 429 (demasiadas peticiones) tumbaba toda la pantalla del tablero QBO-R365. Ahora se maneja y el resto sigue funcionando.', NULL, 'unpriced', NULL, NULL, 1110),
  ('i1-12', '2026-07-20', 'integration', 'new', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Se guarda el identificador de cada respuesta de Intuit, para poder rastrear un problema con ellos.', NULL, 'Trace IDs + 20260720000007_intuit_api_response_logs.sql', 'to_invoice', 3000, NULL, 1120),
  ('i1-13', '2026-07-09', 'integration', 'new', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Registro de las ejecuciones del proceso de recuperación.', 'Queda constancia de cada vez que el sistema intenta recuperar facturas que no salieron.', '20260709000001_qbo_recovery_run_log.sql', 'to_invoice', 3000, NULL, 1130),
  ('i1-14', '2026-07-24', 'integration', 'new', 'i1', '1.1 · Que las facturas lleguen siempre, y una sola vez', 'Cola durable de webhooks de QuickBooks y recuperación diaria por CDC.', 'Cada aviso se guarda antes de procesarse, conserva sus intentos y estados, y una reconciliación diaria recupera documentos cuyo webhook no llegó.', 'qbo_webhook_receipts + reclamos, reintentos y reconciliación CDC · commit 1ced3d1c', 'unpriced', NULL, NULL, 1140),
  ('i2-1', '2026-07-19', 'integration', 'new', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Inicio de sesión con la cuenta de Intuit (Sign in with Intuit).', 'Un cliente que ya usa QuickBooks entra con esa misma cuenta, sin crear otra contraseña.', 'Migraciones 20260717000003 , 20260717000004 , 20260718000001', 'to_invoice', 5000, NULL, 2010),
  ('i2-2', '2026-07-24', 'integration', 'fix', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Después de la verificación en dos pasos, el login con Intuit ya no rebota al principio.', NULL, NULL, 'unpriced', NULL, NULL, 2020),
  ('i2-3', '2026-07-10', 'integration', 'security', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'El identificador de la empresa de QuickBooks se guarda cifrado.', NULL, 'Cifrado de realmId + cabeceras Cache-Control en rutas sensibles', 'to_invoice', 3000, NULL, 2030),
  ('i2-4', '2026-07-20', 'integration', 'security', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Una misma empresa de QuickBooks no puede quedar conectada a dos organizaciones distintas.', NULL, '20260719000002_qbo_realm_ownership.sql', 'unpriced', NULL, NULL, 2040),
  ('i2-5', '2026-07-10', 'integration', 'security', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'El retorno del login de QuickBooks se valida y ya no se puede desviar a otro sitio.', NULL, 'Validación de redirect en el auth callback + endurecimiento del OAuth callback', 'unpriced', NULL, NULL, 2050),
  ('i2-6', '2026-07-10', 'integration', 'new', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Desconectar QuickBooks ahora desconecta de verdad.', 'Antes solo se borraba de nuestro lado; la autorización seguía viva en Intuit.', NULL, 'to_invoice', 2000, NULL, 2060),
  ('i2-7', '2026-07-09', 'integration', 'new', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Botón oficial "Connect to QuickBooks" y cumplimiento completo de la marca Intuit.', 'Requisito para publicar en su tienda: nombre, logo, textos y aviso de marca registrada exactos.', NULL, 'to_invoice', 3000, NULL, 2070),
  ('i2-8', '2026-07-20', 'integration', 'new', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Paquete completo de "listo para revisión de Intuit": retención de datos, soporte y facturación.', NULL, '20260719000001 , 20260720000001 y INTUIT_REVIEW_READINESS.md', 'to_invoice', 7000, NULL, 2080),
  ('i2-9', '2026-07-28', 'integration', 'fix', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'El botón de Intuit aparece solo si la empresa realmente tiene ese plan.', 'Se mostraba también a quien entra desde el lado de plataforma, donde no aplica.', NULL, 'unpriced', NULL, NULL, 2090),
  ('i2-10', '2026-07-28', 'integration', 'fix', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'El puente entre dominios ya no invalida la sesión antes de usarla.', 'Se revocaba el token justo antes de que el otro dominio lo necesitara y el usuario quedaba fuera.', NULL, 'unpriced', NULL, NULL, 2100),
  ('i2-11', '2026-08-05', 'integration', 'new', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Cada campo del modal de conexión tiene al lado una ayuda que explica qué va ahí.', 'Los datos de la configuración de sincronización no eran obvios y había que preguntar. La ayuda se abre hacia abajo cuando arriba no hay espacio en pantalla.', 'Componente compartido shared/ui/field-help.tsx + textos en qbo-r365.i18n.ts', 'to_invoice', 2000, NULL, 2110),
  ('i2-12', '2026-07-26', 'integration', 'security', 'i2', '1.2 · Conectar y desconectar QuickBooks con seguridad', 'Separación estricta entre QuickBooks sandbox y producción.', 'El entorno de desarrollo queda forzado a sandbox y una configuración contradictoria se rechaza antes de hacer una petición, para que una prueba no alcance datos reales.', 'Resolución fail-closed de entorno QBO + cobertura crítica · commit cfab1c37', 'unpriced', NULL, NULL, 2120),
  ('i3-1', '2026-07-10', 'integration', 'new', 'i3', '1.3 · Reportes al dueño y alertas', 'Reporte semanal de operaciones para el dueño de la plataforma.', NULL, 'Servicio de reporte semanal + 20260713000002_qbo_owner_weekly_report_runs.sql', 'previously_invoiced', NULL, 'Página de referido y crons de reporte', 3010),
  ('i3-2', '2026-07-05', 'integration', 'new', 'i3', '1.3 · Reportes al dueño y alertas', 'Reportes separados: uno semanal y otro mensual por organización.', 'Antes iban mezclados y en el idioma equivocado.', NULL, 'previously_invoiced', NULL, 'Página de referido y crons de reporte', 3020),
  ('i3-3', '2026-07-24', 'integration', 'fix', 'i3', '1.3 · Reportes al dueño y alertas', 'El horario y el corte del reporte mensual coinciden con el ciclo de facturación real.', 'Los números del reporte no cuadraban con lo que se cobraba porque las fechas de corte eran distintas.', NULL, 'previously_invoiced', NULL, 'Página de referido y crons de reporte', 3030),
  ('i3-4', '2026-07-13', 'integration', 'fix', 'i3', '1.3 · Reportes al dueño y alertas', 'El reporte semanal ya no se manda dos veces ni se queda colgado.', NULL, NULL, 'previously_invoiced', NULL, 'Página de referido y crons de reporte', 3040),
  ('i3-5', '2026-07-22', 'integration', 'new', 'i3', '1.3 · Reportes al dueño y alertas', 'Página pública de preferencias de correo y baja de suscripción, con enlace propio desde cada reporte.', 'El que recibe el reporte entra desde el correo, sin contraseña, y elige entre tres opciones: semanal , mensual o apagar el reporte . La página le aclara que los avisos de cuenta y facturación siguen llegando igual, porque no se pueden desactivar.', '/email/preferences con token · 20260721000002_qbo_report_preferences.sql y 20260722000002', 'to_invoice', 7000, NULL, 3050),
  ('i3-6', '2026-07-21', 'integration', 'new', 'i3', '1.3 · Reportes al dueño y alertas', 'Los dueños reciben copia de los reportes de integración de sus clientes.', NULL, NULL, 'unpriced', NULL, NULL, 3060),
  ('i3-7', '2026-07-20', 'integration', 'fix', 'i3', '1.3 · Reportes al dueño y alertas', 'El reporte lista solo los fallos de entrega que siguen activos.', 'Arrastraba fallos ya resueltos y parecía que había más problemas de los reales.', NULL, 'previously_invoiced', NULL, 'Página de referido y crons de reporte', 3070),
  ('i3-8', '2026-08-03', 'integration', 'new', 'i3', '1.3 · Reportes al dueño y alertas', 'Herramienta para mandar el reporte semanal a un solo destinatario, para probarlo antes.', NULL, NULL, 'unpriced', NULL, NULL, 3080),
  ('i3-9', '2026-07-09', 'integration', 'new', 'i3', '1.3 · Reportes al dueño y alertas', 'Alertas automáticas de integración al teléfono de todos los superadmin.', NULL, NULL, 'previously_invoiced', NULL, 'Integración QBO→R365: notificación push a superadmin', 3090),
  ('i3-10', '2026-07-30', 'integration', 'new', 'i3', '1.3 · Reportes al dueño y alertas', 'Aviso inmediato cuando se cae la conexión de QuickBooks de un cliente.', NULL, NULL, 'previously_invoiced', NULL, 'Integración QBO→R365: notificación push a superadmin', 3100),
  ('i3-11', '2026-07-30', 'integration', 'fix', 'i3', '1.3 · Reportes al dueño y alertas', 'Las alertas llegan a la campanita aunque el superadmin no tenga las notificaciones del teléfono activadas.', 'Si dependía solo del push, quien no lo tenía prendido nunca se enteraba.', NULL, 'previously_invoiced', NULL, 'Integración QBO→R365: notificación push a superadmin', 3110),
  ('i3-12', '2026-07-24', 'integration', 'fix', 'i3', '1.3 · Reportes al dueño y alertas', 'La tarjeta de facturas del tablero muestra el ciclo de facturación actual, no todo el histórico.', NULL, NULL, 'unpriced', NULL, NULL, 3120),
  ('i3-13', '2026-07-24', 'integration', 'fix', 'i3', '1.3 · Reportes al dueño y alertas', 'La página de baja de suscripción quedó con el logo de GetBackplate y el mismo aspecto que el resto de las páginas públicas.', 'Es una página que el cliente ve fuera de la app, llegando desde un correo: si no tiene la marca, parece de otro lado.', 'email/preferences/page.tsx y preferences.module.css', 'unpriced', NULL, NULL, 3130),
  ('i4-1', '2026-07-16', 'integration', 'new', 'i4', '1.4 · Compras, cobros y correos de facturación', 'El cliente puede comprar conexiones adicionales de R365 desde la app.', NULL, '20260716000002_r365_connection_purchases.sql', 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4010),
  ('i4-2', '2026-07-16', 'integration', 'new', 'i4', '1.4 · Compras, cobros y correos de facturación', 'Recibo automático por cada pago de suscripción exitoso, con el PDF de la factura adjunto.', NULL, NULL, 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4020),
  ('i4-3', '2026-07-24', 'integration', 'new', 'i4', '1.4 · Compras, cobros y correos de facturación', 'El recordatorio de renovación detalla cada concepto y avisa si hay un cargo por uso pendiente.', 'Así nadie se sorprende con un monto distinto al que esperaba.', NULL, 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4030),
  ('i4-4', '2026-08-03', 'integration', 'fix', 'i4', '1.4 · Compras, cobros y correos de facturación', 'Los cobros de Stripe ahora son recuperables.', 'Si el aviso de pago de Stripe falla, se reintenta; si se agotan los intentos, queda apartado con aviso en vez de perderse.', '20260726000010 , 20260803000001/2/3 — ciclo de vida y cola muerta de eventos Stripe', 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4040),
  ('i4-5', '2026-07-24', 'integration', 'fix', 'i4', '1.4 · Compras, cobros y correos de facturación', 'Los correos de facturación llevan a una página que funciona.', 'Apuntaban a /app/billing , que ya no existía tras separar los dominios.', NULL, 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4050),
  ('i4-6', '2026-07-20', 'integration', 'fix', 'i4', '1.4 · Compras, cobros y correos de facturación', 'Todos los correos de facturación usan la marca y el color naranja de GetBackplate.', NULL, NULL, 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4060),
  ('i4-7', '2026-07-14', 'integration', 'fix', 'i4', '1.4 · Compras, cobros y correos de facturación', 'El pago se completa dentro del modal, sin sacar al usuario de la pantalla.', NULL, NULL, 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4070),
  ('i4-8', '2026-07-24', 'integration', 'fix', 'i4', '1.4 · Compras, cobros y correos de facturación', 'Los 4 planes de integración se ven en una sola fila en el modal de ajustes.', NULL, NULL, 'previously_invoiced', NULL, 'Links de suscripción, Stripe y precio por factura', 4080),
