  ('i8-3', '2026-08-06', 'integration', 'security', 'i8', '1.8 · Preparación completa para el review de Intuit', 'Credenciales y entorno productivo de QuickBooks configurados explícitamente.', 'Se restauró la clave correcta de cifrado de integraciones, se declaró QBO_ENVIRONMENT=production y se comprobó que los secretos almacenados se pueden descifrar.', NULL, 'unpriced', NULL, NULL, 8030),
  ('i8-4', '2026-08-06', 'integration', 'new', 'i8', '1.8 · Preparación completa para el review de Intuit', 'Compañía QuickBooks Online productiva dedicada conectada a Intuit Review.', 'El grant OAuth, el customer y todos los documentos usados por el reviewer pertenecen a esa compañía de prueba controlada.', NULL, 'unpriced', NULL, NULL, 8040),
