  ('p1-12', '2026-07-31', 'platform', 'docs', 'p1', '2.1 · Quién ve qué — el alcance', 'Documentado por qué las sucursales viven en tres tablas y cómo se resuelven las de una persona.', NULL, 'Eliminada la tabla duplicada announcement_audiences ( 20260729000004 )', 'unpriced', NULL, NULL, 9120),
